<?php use App\Core\Db; $pdo=Db::pdo(); $u=\App\Core\Auth::user(); $uid=(int)$u['id']; $rows=array(); if($pdo&&$uid){$st=$pdo->prepare("SELECT d.*,l.role_type current_role FROM cpms_approval_documents d LEFT JOIN cpms_approval_lines l ON l.document_id=d.id AND l.line_order=d.current_step_order WHERE d.created_by_id=:u OR (l.approver_id=:u AND l.line_status='PENDING') ORDER BY d.id DESC LIMIT 100");$st->execute(array(':u'=>$uid));$rows=$st->fetchAll();} ?>
<div class="bg-white rounded-2xl p-6 border"><h2 class="text-2xl font-bold mb-4">전자결재</h2><a href="?r=approval_create&type=proposal">품의서 작성</a> | <a href="?r=approval_create&type=leave">휴가계 작성</a><table class="w-full text-sm mt-3"><tr><th>ID</th><th>종류</th><th>제목</th><th>상태</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?php echo (int)$r['id'];?></td><td><?php echo h($r['doc_type']);?></td><td><?php echo h($r['title']);?></td><td><?php echo h($r['doc_status']);?></td><td><a href="?r=approval_detail&id=<?php echo (int)$r['id'];?>">상세</a></td></tr><?php endforeach;?></table></div>